import{_ as e,o as a,c as n,a3 as l}from"./chunks/framework.DXf0zkj5.js";const m=JSON.parse('{"title":"Technical Debt, Known Gaps & Future Improvements","description":"","frontmatter":{},"headers":[],"relativePath":"10-gaps-and-improvements.md","filePath":"10-gaps-and-improvements.md"}'),r={name:"10-gaps-and-improvements.md"};function i(s,t,o,d,c,p){return a(),n("div",null,[...t[0]||(t[0]=[l('<h1 id="technical-debt-known-gaps-future-improvements" tabindex="-1">Technical Debt, Known Gaps &amp; Future Improvements <a class="header-anchor" href="#technical-debt-known-gaps-future-improvements" aria-label="Permalink to &quot;Technical Debt, Known Gaps &amp; Future Improvements&quot;">​</a></h1><p>This document outlines the architectural trade-offs, known gaps, and engineering roadmap for <code>17-cdn-caching-proxy</code>.</p><hr><h2 id="_1-ranked-technical-gaps-roadmap" tabindex="-1">1. Ranked Technical Gaps &amp; Roadmap <a class="header-anchor" href="#_1-ranked-technical-gaps-roadmap" aria-label="Permalink to &quot;1. Ranked Technical Gaps &amp; Roadmap&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Priority</th><th style="text-align:left;">Gap Title</th><th style="text-align:left;">Description</th><th style="text-align:left;">Remediation Plan</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>P1</strong></td><td style="text-align:left;">Distributed Purge Mesh</td><td style="text-align:left;">Purge events are currently in-process or relayed via peer HTTP calls. In large clusters, a node network partition can cause stale cache states.</td><td style="text-align:left;">Implement a distributed Redis Pub/Sub or Kafka invalidation bus with vector clocks for cluster-wide cache invalidation.</td></tr><tr><td style="text-align:left;"><strong>P2</strong></td><td style="text-align:left;">Persistent RocksDB Storage</td><td style="text-align:left;"><code>DiskStore</code> relies on flat segment files with manual compaction. Under extreme write churn, fragmentation increases disk I/O.</td><td style="text-align:left;">Integrate embedded RocksDB or LMDB via native bindings for LSM-tree SSD caching.</td></tr><tr><td style="text-align:left;"><strong>P3</strong></td><td style="text-align:left;">HTTP/3 (QUIC) Ingress</td><td style="text-align:left;">Proxy listener currently supports HTTP/1.1 and HTTPS. Clients on mobile networks experience TCP head-of-line blocking.</td><td style="text-align:left;">Introduce HTTP/3 and QUIC protocol support using Node.js experimental quic or an eBPF front-door envoy proxy.</td></tr><tr><td style="text-align:left;"><strong>P4</strong></td><td style="text-align:left;">Off-Heap Slab Allocation</td><td style="text-align:left;">While memory leak tests pass, large Buffers in V8 memory trigger heap compaction during peak allocations.</td><td style="text-align:left;">Implement an off-heap native C++ memory arena with fixed 64KB slab allocators.</td></tr></tbody></table><hr><h2 id="_2-technical-debt-knowingly-taken" tabindex="-1">2. Technical Debt Knowingly Taken <a class="header-anchor" href="#_2-technical-debt-knowingly-taken" aria-label="Permalink to &quot;2. Technical Debt Knowingly Taken&quot;">​</a></h2><ol><li><strong>In-Memory Flight Map</strong>: Request coalescing tracks flights in a local JavaScript <code>Map</code>. This is exceptionally fast, but limits coalescing to requests arriving on the exact same proxy instance.</li><li><strong>Simplified Zstandard Support</strong>: Zstandard compression leverages native Node.js zlib where supported, falling back to Brotli on systems without zstd bindings.</li></ol>',8)])])}const h=e(r,[["render",i]]);export{m as __pageData,h as default};
